					"codice": "extends \"res://htd/htd_test.gd\"\n\n\nfunc _run_tests() -> void:\n\tvar basket := await instantiate_main_scene()\n\tif not check(\"basket\", basket != null, \"La scena principale basket.tscn deve istanziarsi correttamente\"):\n\t\treturn\n\n\tcheck(\"freeze_fn\", has_function(basket, \"activate_freeze_powerup\"), \"basket.gd deve avere il metodo activate_freeze_powerup()\")\n\tcheck(\"alchemy_fn\", has_function(basket, \"activate_alchemy_powerup\"), \"basket.gd deve avere il metodo activate_alchemy_powerup()\")\n\n\tvar falling_items := get_tree().get_nodes_in_group(\"falling_items\")\n\tcheck(\"items_in_group\", falling_items.size() > 0, \"Gli elementi generati all'inizio devono appartenere al gruppo falling_items\")\n\n\tvar first_item: Node2D = falling_items[0] as Node2D\n\tvar prev_y: float = first_item.position.y\n\n\tcall_if_exists(basket, \"activate_freeze_powerup\")\n\tawait wait_seconds(0.3)\n\tcheck(\"is_frozen\", abs(first_item.position.y - prev_y) < 1.0, \"Dopo activate_freeze_powerup() gli oggetti del gruppo falling_items non devono scendere\")\n\n\tvar rocks_before := get_tree().get_nodes_in_group(\"rocks\")\n\tcheck(\"rocks_present\", rocks_before.size() > 0, \"Ci devono essere rocce nel gruppo rocks\")\n\n\tcall_if_exists(basket, \"activate_alchemy_powerup\")\n\tawait wait_frames(2)\n\tvar rocks_after := get_tree().get_nodes_in_group(\"rocks\")\n\tvar active_rocks_count: int = 0\n\tfor r in rocks_after:\n\t\tif is_instance_valid(r) and not r.is_queued_for_deletion():\n\t\t\tactive_rocks_count += 1\n\tcheck(\"alchemy_done\", active_rocks_count == 0, \"Dopo activate_alchemy_powerup() tutte le rocce devono essere state rimosse e sostituite\")\n"
